    "content": "中新网北京8月28日电 (记者 吕少威)记者28日从北京市交通委获悉，9月1日(周二)为北京中小学秋季开学日，通勤、通学客流叠加，预计8:00-8:15交通压力集中。北京交通部门已启动开学日专项保障，重点加强公共交通运力统筹和现场疏导，全力保障市民出行平稳有序。倡导市民绿色出行、错峰出行。"
