    "content": "8月30日至9月3日，国家主席习近平将出席在比什凯克举行的2026年上海合作组织峰会，并对吉尔吉斯斯坦、埃及进行国事访问。 2013年以来，习近平主席出席上合组织历次峰会，提出一系列重要主张，推动以“互信、互利、平等、协商、尊重多样文明、谋求共同发展”为核心内涵的“上海精神”不断焕发时代光彩。 今年是上合组织成立25周年。25年来，成员国共享机遇、共谋发展，推动上合组织建设和合作取得一系列开创性成果、历史性成就。如今，上合组织已成为世界上幅员最广、人口最多、发展潜力巨大的综合性区域合作组织，“上海精神”始终引领上合…"
