    "author": "Sawallianc",
    "description": "如题，研究了一个目前几个头部的一键平台，效果虽然非常好，但是视频长度有限。我想的是一句话由模型扩充剧本再分镜，定妆、定角色、定场景呢，中间产物可以吐给前端让用户自己决策要不要调整。最后再生成分镜视频最后剪辑成终片。这里其实很多东西都是可以并行走的，利用 k8s 水平扩展能力提供并发和并行能力。 视频的类型包括真人视频、漫剧、动漫、电商广告和品牌广告以及教育相关宣传视频等。 有没有朋友在这方面有经验的（市场经验和技术经验都可）来交流下啊",
