    "description": "新华社福州8月28日电（记者张华迎、陈弘毅）面对台风“沙德尔”和近期强降雨来袭，福建各地各部门抓住台风登陆前的窗口期、降雨间歇期，持续抓好风险隐患巡查排查，积极做好应对工作。记者从福建省防指获悉，截至8月28日7时，福建累计下沉干部13.77万人，转移海上、陆上危险区域人员24.77万人。 同时，福建积极强化救援准备，努力降低灾害影响。据福建省防指通报，截至8月28日7时，福建已统筹驻闽部队、消防救援队伍、地方应急力量和社会救援力量8.…",
    "content": "新华社福州8月28日电（记者张华迎、陈弘毅）面对台风“沙德尔”和近期强降雨来袭，福建各地各部门抓住台风登陆前的窗口期、降雨间歇期，持续抓好风险隐患巡查排查，积极做好应对工作。记者从福建省防指获悉，截至8月28日7时，福建累计下沉干部13.77万人，转移海上、陆上危险区域人员24.77万人。 同时，福建积极强化救援准备，努力降低灾害影响。据福建省防指通报，截至8月28日7时，福建已统筹驻闽部队、消防救援队伍、地方应急力量和社会救援力量8.08万人、装备8万余台（套）全时备勤；强化力量预置，调度省级救援力量15支队伍1…"
