    "title": "马上评｜“镜头霸凌”九旬老人？别为流量失了做人的底线",
    "link": "https://m.thepaper.cn/detail/33965970",
    "pub_date": "2026-08-28 13:16:31",
    "author": "澎湃评论员 阳柳",
    "description": "薛婆婆遭遇“镜头霸凌”。 近日，四川成都92岁蛋烘糕摊主薛婆婆遭遇“镜头霸凌”，引发热议。一些短视频博主围堵薛婆婆小摊，不买蛋烘糕，只怼脸拍摄，反复骚扰刺激老人，趁其疲惫烦躁时拍下失控画面，再断章取义剪成“恶婆婆骂人”等标题视频博流量。 8月27日晚，成都市成华区互联网信息办公室发布情况通报称，短视频平台账号“卤**”“副***”通过剧情摆拍、恶意拼接剪辑、使用夸张标题等方式拍摄视频，炒作“蛋烘糕婆婆”话题，侵害其名誉、隐私等合法权益。…",
