    "author": "张粲,孙一然",
    "description": "新华社首尔8月28日电（记者张粲 孙一然）据韩国媒体28日报道，韩国忠清南道天安市一家油漆原料生产厂当天发生火灾，已造成3人死亡、4人受伤。 报道说，当地时间11时44分许，这家位于天安市东南区的工厂发生火灾。消防人员接警后赶赴现场灭火，在现场发现3具遗体。至少4人因烧伤被送医。起火原因尚待调查。",
    "content": "新华社首尔8月28日电（记者张粲 孙一然）据韩国媒体28日报道，韩国忠清南道天安市一家油漆原料生产厂当天发生火灾，已造成3人死亡、4人受伤。 报道说，当地时间11时44分许，这家位于天安市东南区的工厂发生火灾。消防人员接警后赶赴现场灭火，在现场发现3具遗体。至少4人因烧伤被送医。起火原因尚待调查。"
