    "description": "36氪获悉，香港交易所今天宣布，将于希音国际控股有限公司在2026年9月1日上市时，推出下列产品和措施：一、希音每周及每月期权将于2026年9月1日希音股份上市日同日推出；二、与希音股份相关的衍生权证可于该股份在香港交易所证券市场上市当日挂牌；三、希音股份于2026年9月1日在香港交易所上市后，将于同日纳入可进行卖空的指定证券名单。",
    "content": "36氪获悉，香港交易所今天宣布，将于希音国际控股有限公司在2026年9月1日上市时，推出下列产品和措施：一、希音每周及每月期权将于2026年9月1日希音股份上市日同日推出；二、与希音股份相关的衍生权证可于该股份在香港交易所证券市场上市当日挂牌；三、希音股份于2026年9月1日在香港交易所上市后，将于同日纳入可进行卖空的指定证券名单。"
