    "description": "8月28日上午，北京市大兴区人民法院、天津市静海区人民法院、天津市蓟州区人民法院、河北省唐山市曹妃甸区人民法院、上海市第二中级人民法院、安徽省舒城县人民法院、江西省丰城市人民法院、山东省日照市东港区人民法院、湖北省远安县人民法院、贵州省纳雍县人民法院、云南省丽江市中级人民法院对12件黑恶犯罪案件一审公开宣判，对12个黑恶犯罪组织、163名被告人依法判处无期徒刑至有期徒刑10个月不等的刑罚。",
    "content": "8月28日上午，北京市大兴区人民法院、天津市静海区人民法院、天津市蓟州区人民法院、河北省唐山市曹妃甸区人民法院、上海市第二中级人民法院、安徽省舒城县人民法院、江西省丰城市人民法院、山东省日照市东港区人民法院、湖北省远安县人民法院、贵州省纳雍县人民法院、云南省丽江市中级人民法院对12件黑恶犯罪案件一审公开宣判，对12个黑恶犯罪组织、163名被告人依法判处无期徒刑至有期徒刑10个月不等的刑罚。"
