    "pub_date": "2026-08-28 12:36:26",
    "author": "",
    "description": "36氪获悉，龙湖集团公告，2026年上半年实现营收398亿元，其中，地产开发业务收入为261.0亿元，运营业务收入为73.0亿元，服务业务收入为64.0亿元。运营及服务业务收入合计为137.0亿元，同比增长3.2%，占总营业收入34.4%。上半年公司拥有人应占溢利为19.6亿元，剔除投资物业及其他衍生金融工具公平值变动影响后之公司拥有人应占核心溢利为0.64亿元。",
