    "content": "新华社伦敦8月27日电 记者手记｜烈日之下的英国之困 新华社记者张枫 于艾岑 英格兰莱斯特郡的田野上，高温炙烤着干裂的土地。一阵热风吹过，卷起细碎的尘土，目之所及尽是枯黄。37岁的农场主威廉·奥利弗手持铁锹，缓步走向自家麦田。 “今年的干旱不同寻常。”奥利弗望着收割后留下的麦茬，神情低落。他告诉记者，往年8月下旬才是小麦收获的时节，但今年受持续高温干旱影响，为减少对作物的损害，收割时间不得不提前3周。同时，高温天气增加了农田火灾风险，收割机作业时产生的火花稍有不慎就可能引燃干燥的麦田，因此收割过程需格外小心。 奥利…"
