    "content": "新华社北京8月28日电（记者魏玉坤）记者28日从国家发展改革委获悉，近日，经国务院同意，国家发展改革委、交通运输部联合印发《物流网建设实施方案》。 物流网由枢纽节点、骨干通道、装备载具、规则标准、信息数据等有机构成，是支撑全社会商品和资源高效流转的复合型基础设施体系和综合性服务网络，是经济社会高质量发展的重要基础。 实施方案提出，到2030年，物流网建设取得明显成效，有效实现枢纽与产业紧密协同、通道与网络内外联通、设施与装备绿色智能、规则与信息全域互通，促进有效降低全社会物流成本，推动社会物流总费用与国内生产总值（…"
