    "content": "近日，一张四川省雷波县2026年秋季教育行政会图片在网络流传，会上，一批班级平均分在15分以下的初中老师被请到台上合影，背后大屏幕两个大字格外刺眼：“耻辱”。8月28日上午，澎湃新闻从凉山州教育局核实到，该图片及会议情况均属实，目前当地已启动调查，具体缘由正在进一步了解中。 网传会议图片，经证实为真。 澎湃新闻从图片中看到，该场会议召开时间为8月26日，会议是雷波县2026年秋季教育行政会，台上有20余名身着白衬衫和黑西裤的教师，台下坐满参会人员。上台合影的教师身后大屏写着“雷波县2025-2026学年初中期末考试…"
