    "author": "张曦月",
    "description": "新华社哈尔滨8月28日电（记者张曦月）黑龙江省孙吴县，是一个边疆小城，因得天独厚的资源条件和区位优势，近年来大力发展安格斯牛特色产业。在这里，安格斯牛的日子颇有些“讲究”。 牛舍里放着舒缓的音乐，一头头黑色安格斯牛低头嚼着草料，饲料中拌有当地沙棘加工后的果渣，脚下铺着汉麻垫料。走近些，牛耳上还挂着耳标，像随身带着的“身份证”。 黑龙江省孙吴县安格斯牛养殖场内，佩戴耳标的安格斯牛。新华社记者 那宇奇 摄 吃什么、住什么有讲究，怎么选出一头…",
    "content": "新华社哈尔滨8月28日电（记者张曦月）黑龙江省孙吴县，是一个边疆小城，因得天独厚的资源条件和区位优势，近年来大力发展安格斯牛特色产业。在这里，安格斯牛的日子颇有些“讲究”。 牛舍里放着舒缓的音乐，一头头黑色安格斯牛低头嚼着草料，饲料中拌有当地沙棘加工后的果渣，脚下铺着汉麻垫料。走近些，牛耳上还挂着耳标，像随身带着的“身份证”。 黑龙江省孙吴县安格斯牛养殖场内，佩戴耳标的安格斯牛。新华社记者 那宇奇 摄 吃什么、住什么有讲究，怎么选出一头好牛，更有门道。 “测眼肌面积，要找这里。”孙吴县援边工作队队员、县畜牧技术推广…"
